import crypto from 'node:crypto';

/** Match the deterministic owner UUID generated by the per-vendor migration. */
export function vendorOwnerIdForSlug(slug) {
  if (!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(slug)) {
    throw new Error(`Invalid vendor slug for owner identity: ${slug}`);
  }

  const hex = crypto.createHash('md5').update(`vendor-owner:${slug}`).digest('hex');
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
}
